import { BillingSettings } from "./billing-settings";

export function BillingPage() {
  return (
    <main className="min-h-svh bg-background px-5 py-10 sm:px-8">
      <div className="mx-auto max-w-4xl">
        <BillingSettings />
      </div>
    </main>
  );
}

"use client";

import { CreditCardIcon, DownloadSimpleIcon } from "@phosphor-icons/react";
import { useState } from "react";
import { Alert } from "../../vip-ui/alert";
import { Badge } from "../../vip-ui/badge";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import { Meter } from "../../vip-ui/meter";
import {
  RadioButton,
  RadioDescription,
  RadioField,
  RadioGroup,
  RadioIndicator,
  RadioLabel,
} from "../../vip-ui/radio-group";
import {
  Cell,
  Column,
  Row,
  Table,
  TableBody,
  TableHeader,
} from "../../vip-ui/table";
import { showToast } from "../../vip-ui/toast";
import { ConfirmPlanDialog } from "./confirm-plan-dialog";
import { type PaymentCard, PaymentMethodDialog } from "./payment-method-dialog";

export const plans = [
  {
    id: "starter",
    name: "Starter",
    price: 0,
    seats: 3,
    description: "3 seats and 10 GB of storage",
  },
  {
    id: "pro",
    name: "Pro",
    price: 24,
    seats: 10,
    description: "10 seats and 100 GB of storage",
  },
  {
    id: "business",
    name: "Business",
    price: 59,
    seats: 50,
    description: "50 seats, 1 TB of storage, and SSO",
  },
];

export type Plan = (typeof plans)[number];

const seatsUsed = 8;

const usage = [
  { label: "Seats", value: seatsUsed, max: 10, unit: "seats" },
  { label: "Storage", value: 42, max: 100, unit: "GB" },
  { label: "API requests", value: 74, max: 100, unit: "thousand" },
];

const invoices = [
  { id: "INV-0042", date: "Oct 1, 2026", dateTime: "2026-10-01", amount: 24 },
  { id: "INV-0037", date: "Sep 1, 2026", dateTime: "2026-09-01", amount: 24 },
  { id: "INV-0031", date: "Aug 1, 2026", dateTime: "2026-08-01", amount: 24 },
  { id: "INV-0026", date: "Jul 1, 2026", dateTime: "2026-07-01", amount: 24 },
];

const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});

export function BillingSettings() {
  const [current, setCurrent] = useState("pro");
  const [selected, setSelected] = useState("pro");
  const [confirming, setConfirming] = useState(false);
  const [card, setCard] = useState<PaymentCard>({
    brand: "Visa",
    last4: "4242",
    expiry: "08/28",
  });
  const plan = plans.find((item) => item.id === current) ?? plans[0];
  const next = plans.find((item) => item.id === selected) ?? plans[0];
  const changed = selected !== current;
  const tooSmall = next.seats < seatsUsed;

  return (
    <div className="grid gap-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-[-0.04em]">Billing</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Manage your plan, usage, and payment details.
        </p>
      </div>
      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,20rem)]">
        <Card>
          <CardHeader>
            <CardTitle as="h2">Plan</CardTitle>
            <CardDescription>
              You use the {plan.name} plan. It renews on November 1.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-4">
            <RadioGroup
              aria-label="Plan"
              value={selected}
              onChange={setSelected}
              className="gap-2"
            >
              {plans.map((item) => (
                <RadioField key={item.id} value={item.id} variant="card">
                  <RadioButton>
                    <RadioIndicator />
                    <RadioLabel className="flex flex-1 flex-wrap items-center gap-2">
                      {item.name}
                      {item.id === current && (
                        <Badge variant="accent" className="min-h-5 py-0">
                          Current
                        </Badge>
                      )}
                    </RadioLabel>
                    <span className="font-semibold tabular-nums">
                      ${item.price}
                      <span
                        aria-hidden="true"
                        className="font-normal text-muted-foreground"
                      >
                        /mo
                      </span>
                      <span className="sr-only"> per month</span>
                    </span>
                  </RadioButton>
                  <RadioDescription>{item.description}</RadioDescription>
                </RadioField>
              ))}
            </RadioGroup>
            {changed && tooSmall && (
              <Alert
                variant="warning"
                title={`${next.name} has ${next.seats} seats. You use ${seatsUsed}.`}
              >
                Remove {seatsUsed - next.seats} members before you change to
                this plan.
              </Alert>
            )}
          </CardContent>
          <CardFooter className="justify-end border-t border-border/70 pt-5">
            <Button
              variant="ghost"
              isDisabled={!changed}
              onPress={() => setSelected(current)}
            >
              Cancel
            </Button>
            <Button
              isDisabled={!changed || tooSmall}
              onPress={() => setConfirming(true)}
            >
              Change plan
            </Button>
          </CardFooter>
        </Card>
        <div className="grid content-start gap-6">
          <Card>
            <CardHeader>
              <CardTitle as="h2">Usage</CardTitle>
              <CardDescription>Oct 1 to Oct 31</CardDescription>
            </CardHeader>
            <CardContent className="grid gap-4">
              {usage.map((item) => (
                <Meter
                  key={item.label}
                  label={item.label}
                  value={item.value}
                  maxValue={item.max}
                  valueLabel={`${item.value} of ${item.max} ${item.unit}`}
                  className="[&_[data-slot=meter-value]]:text-xs"
                />
              ))}
            </CardContent>
          </Card>
          <Card>
            <CardHeader>
              <CardTitle as="h2">Payment method</CardTitle>
            </CardHeader>
            <CardContent className="flex items-center gap-3">
              <span className="grid size-10 shrink-0 place-items-center rounded-md bg-muted ring-1 ring-border/70">
                <CreditCardIcon size={20} aria-hidden="true" />
              </span>
              <div className="min-w-0 flex-1 text-sm">
                <p className="truncate font-medium">
                  {card.brand} ending in {card.last4}
                </p>
                <p className="text-xs text-muted-foreground">
                  Expires {card.expiry}
                </p>
              </div>
              <PaymentMethodDialog
                onSave={(nextCard) => {
                  setCard(nextCard);
                  showToast({
                    title: "Card updated",
                    description: `We charge ${nextCard.brand} ending in ${nextCard.last4} from Nov 1.`,
                    variant: "success",
                  });
                }}
              />
            </CardContent>
          </Card>
        </div>
      </div>
      <Card className="overflow-hidden">
        <CardHeader>
          <CardTitle as="h2">Invoices</CardTitle>
        </CardHeader>
        <div className="overflow-x-auto">
          <Table aria-label="Invoices" className="min-w-[480px]">
            <TableHeader>
              <Column isRowHeader className="ps-5">
                Invoice
              </Column>
              <Column>Date</Column>
              <Column>Status</Column>
              <Column className="text-end">Amount</Column>
              <Column className="w-14 pe-3">
                <span className="sr-only">Download</span>
              </Column>
            </TableHeader>
            <TableBody items={invoices}>
              {(invoice) => (
                <Row id={invoice.id}>
                  <Cell className="ps-5 font-mono text-xs">{invoice.id}</Cell>
                  <Cell className="text-muted-foreground">
                    <time dateTime={invoice.dateTime}>{invoice.date}</time>
                  </Cell>
                  <Cell>
                    <Badge variant="success">Paid</Badge>
                  </Cell>
                  <Cell className="text-end font-medium tabular-nums">
                    {money.format(invoice.amount)}
                  </Cell>
                  <Cell className="pe-3">
                    <Button
                      variant="ghost"
                      iconOnly
                      aria-label={`Download ${invoice.id}`}
                      className="size-9"
                      onPress={() =>
                        showToast({
                          title: `${invoice.id}.pdf is downloading`,
                        })
                      }
                    >
                      <DownloadSimpleIcon size={17} aria-hidden="true" />
                    </Button>
                  </Cell>
                </Row>
              )}
            </TableBody>
          </Table>
        </div>
      </Card>
      <ConfirmPlanDialog
        isOpen={confirming}
        onOpenChange={setConfirming}
        from={plan}
        to={next}
        onConfirm={() => {
          setCurrent(next.id);
          showToast({
            title: `You now use the ${next.name} plan`,
            variant: "success",
          });
        }}
      />
    </div>
  );
}

"use client";

import { Button } from "../../vip-ui/button";
import {
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import type { Plan } from "./billing-settings";

const daysInPeriod = 31;
const daysLeft = 18;

const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});

export function ConfirmPlanDialog({
  isOpen,
  onOpenChange,
  from,
  to,
  onConfirm,
}: {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  from: Plan;
  to: Plan;
  onConfirm: () => void;
}) {
  const upgrade = to.price > from.price;
  const difference = ((to.price - from.price) * daysLeft) / daysInPeriod;

  return (
    <DialogContent
      role="alertdialog"
      size="sm"
      overlayProps={{ isOpen, onOpenChange }}
    >
      <DialogHeader>
        <DialogTitle>Change to {to.name}?</DialogTitle>
        <DialogDescription>
          {upgrade
            ? `You pay ${money.format(difference)} today for the ${daysLeft} days left in this period. From Nov 1, you pay ${money.format(to.price)} each month.`
            : `The change starts today. We add a credit of ${money.format(-difference)} to your next invoice.`}
        </DialogDescription>
      </DialogHeader>
      <DialogFooter>
        <DialogClose variant="outline">Cancel</DialogClose>
        <Button
          onPress={() => {
            onConfirm();
            onOpenChange(false);
          }}
        >
          {upgrade ? `Pay ${money.format(difference)}` : "Change plan"}
        </Button>
      </DialogFooter>
    </DialogContent>
  );
}

"use client";

import { Button } from "../../vip-ui/button";
import {
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import { Form } from "../../vip-ui/form";
import { TextField } from "../../vip-ui/text-field";

export interface PaymentCard {
  brand: string;
  last4: string;
  expiry: string;
}

const brands = [
  { pattern: /^4/, name: "Visa" },
  { pattern: /^(5[1-5]|2[2-7])/, name: "Mastercard" },
  { pattern: /^3[47]/, name: "American Express" },
];

function digits(value: string) {
  return value.replace(/\D/g, "");
}

function validateNumber(value: string) {
  const number = digits(value);
  if (number.length < 13 || number.length > 19)
    return "Enter the 13 to 19 digits on the front of the card.";
  let sum = 0;
  for (let index = 0; index < number.length; index++) {
    let digit = Number(number[number.length - 1 - index]);
    if (index % 2 === 1) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
  }
  return sum % 10 === 0 ? null : "This card number is not correct.";
}

function validateExpiry(value: string) {
  const match = value.trim().match(/^(\d{2})\s*\/\s*(\d{2})$/);
  if (!match) return "Use the format MM/YY.";
  const month = Number(match[1]);
  const year = 2000 + Number(match[2]);
  if (month < 1 || month > 12) return "Enter a month from 01 to 12.";
  if (year < 2026 || (year === 2026 && month < 10))
    return "This card has expired.";
  return null;
}

export function PaymentMethodDialog({
  onSave,
}: {
  onSave: (card: PaymentCard) => void;
}) {
  return (
    <Dialog>
      <Button variant="outline" size="sm">
        Update
      </Button>
      <DialogContent size="sm">
        {({ close }) => (
          <>
            <DialogHeader>
              <DialogTitle>Update card</DialogTitle>
              <DialogDescription>
                We charge this card for your plan from the next invoice.
              </DialogDescription>
              <DialogClose />
            </DialogHeader>
            <Form
              className="contents"
              onSubmit={(event) => {
                event.preventDefault();
                const data = new FormData(event.currentTarget);
                const number = digits(String(data.get("number")));
                onSave({
                  brand:
                    brands.find((brand) => brand.pattern.test(number))?.name ??
                    "Card",
                  last4: number.slice(-4),
                  expiry: String(data.get("expiry")).replace(/\s/g, ""),
                });
                close();
              }}
            >
              <DialogBody className="grid content-start gap-4">
                <TextField
                  name="name"
                  label="Name on card"
                  autoComplete="cc-name"
                  defaultValue="Maya Chen"
                  isRequired
                />
                <TextField
                  name="number"
                  label="Card number"
                  autoComplete="cc-number"
                  inputMode="numeric"
                  placeholder="1234 1234 1234 1234"
                  validate={validateNumber}
                  isRequired
                  autoFocus
                />
                <div className="grid grid-cols-2 gap-4">
                  <TextField
                    name="expiry"
                    label="Expiry date"
                    autoComplete="cc-exp"
                    inputMode="numeric"
                    placeholder="MM/YY"
                    validate={validateExpiry}
                    isRequired
                  />
                  <TextField
                    name="cvc"
                    label="Security code"
                    autoComplete="cc-csc"
                    inputMode="numeric"
                    placeholder="CVC"
                    validate={(value) =>
                      /^\d{3,4}$/.test(value) ? null : "Enter 3 or 4 digits."
                    }
                    isRequired
                  />
                </div>
              </DialogBody>
              <DialogFooter>
                <DialogClose variant="outline">Cancel</DialogClose>
                <Button type="submit">Save card</Button>
              </DialogFooter>
            </Form>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}
